  function input(label,name,value,type='text',extra='',hint=''){return '<label class="field"><span>'+label+'</span><input type="'+type+'" name="'+name+'" value="'+esc(value)+'" '+extra+'>'+(hint?'<span class="hint">'+hint+'</span>':'')+'</label>';}
