      const saved=loadLocal(),save=()=>localStorage.setItem(KEY,JSON.stringify(saved)),repo=new S.MemoryRepo(saved.data,save),cal=new S.MockCalendar(saved.events,save),engine=new S.Engine(repo,cal);input=input||{};
      switch(action){case 'snapshot':return Object.assign(engine.snapshot(),{sample:saved.sample});case 'preview':return engine.preview(input.start?input:null);case 'generate':S.need(input.confirm,'Confirm generation.');return engine.generate(input.range);case 'saveStudent':case 'saveSchedule':case 'createLesson':case 'reschedule':case 'attend':case 'notes':case 'saveSettings':return engine[action](input);case 'cancel':return engine.cancel(input.lesson_id);case 'retry':return engine.sync(input.lesson_id,true);case 'reconcile':return engine.reconcileAll();case 'clearDevelopment':S.need(input.confirm,'Confirm clearing development lessons.');saved.data.Lessons=[];saved.data.AutomationLogs=[];saved.events={};saved.sample=false;save();return {cleared:true};case 'disableAutomation':case 'disableLive':return {};default:S.fail('Google connection and background automation are available after deploying to Apps Script. This browser is in development mode.','DEVELOPMENT');}
