  async function call(action,input){if(!GAS)return localCall(action,input);return new Promise((resolve,reject)=>google.script.run.withSuccessHandler(r=>{if(r.ok)resolve(r.data);else{const e=Error(r.error.message);e.code=r.error.code;reject(e);}}).withFailureHandler(()=>reject(Error('Cannot reach Apps Script. Check authorization and your connection.'))).api(action,input||{}));}
  function toast(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').className='show'+(error?' error':'');toastTimer=setTimeout(()=>$('#toast').className='',error?9000:5000);}
